-- ----------------------------
-- Table structure for kb_doc_chunk
-- ----------------------------
DROP TABLE IF EXISTS "public"."kb_doc_chunk";
CREATE TABLE "public"."kb_doc_chunk" (
  "id" int8 NOT NULL DEFAULT nextval('kb_doc_chunk_id_seq'::regclass),
  "doc_id" int8 NOT NULL,
  "kb_id" int8 NOT NULL,
  "chunk_index" int4 NOT NULL,
  "content" text COLLATE "pg_catalog"."default" NOT NULL,
  "content_tsv" tsvector,
  "embedding" "public"."vector" NOT NULL,
  "page_num" int4,
  "section_title" varchar(500) COLLATE "pg_catalog"."default",
  "token_count" int4 NOT NULL DEFAULT 0,
  "doc_version" int4 NOT NULL,
  "created_at" timestamp(6) NOT NULL DEFAULT now()
)
;
COMMENT ON COLUMN "public"."kb_doc_chunk"."content_tsv" IS '全文检索向量，由触发器自动更新';
COMMENT ON COLUMN "public"."kb_doc_chunk"."doc_version" IS '冗余版本号，重建索引后删除旧版本时使用';
COMMENT ON TABLE "public"."kb_doc_chunk" IS '文档分块表，每条记录是一个可检索的最小单元';

-- ----------------------------
-- Records of kb_doc_chunk
-- ----------------------------
INSERT INTO "public"."kb_doc_chunk" VALUES (185, 7, 2, 0, '技术规范文档 v1.4
技术委员会 2025 年修订版

第一章 代码规范

1.1 提交规范

所有代码提交必须遵循以下 Commit Message 格式：

type(scope): message

type 类型：
- feat：新功能。
- fix：Bug 修复。
- docs：文档修改。
- refactor：重构，不影响功能。
- perf：性能优化。
- test：测试相关。
- chore：构建工具、依赖等变更。

示例：

feat(payment): 新增微信支付接口
fix(order): 修复订单金额计算精度问题

1.2 分支策略

主要分支：
- main：生产环境代码，只接受来自 release 分支的 PR。
- develop：开发主分支，日常开发在此基础上创建特性分支。
- feature/xxx：特性开发分支，从 develop 创建，完成后 PR 到 develop。
