INSERT INTO "public"."kb_doc_chunk" VALUES (189, 7, 2, 4, '4.2 SQL 注入防护

- 禁止拼接 SQL 字符串，全部使用参数化查询。
- ORM 框架的动态查询必须使用预编译语句。
- AI 系统中模型生成的参数，必须经过白名单校验后才能传入查询。

4.3 敏感数据处理

- 密码必须使用 BCrypt 加密存储。
- 手机号、身份证等 PII 数据展示时进行脱敏处理。
- 禁止在日志中打印完整敏感信息。', '''4.2'':1 ''4.3'':13 ''ai'':10 ''bcrypt'':16 ''orm'':8 ''pii'':20 ''sql'':2,5 ''全部使用参数化查询'':7 ''加密存储'':17 ''字符串'':6 ''密码必须使用'':15 ''必须经过白名单校验后才能传入查询'':12 ''手机号'':18 ''敏感数据处理'':14 ''数据展示时进行脱敏处理'':21 ''框架的动态查询必须使用预编译语句'':9 ''注入防护'':3 ''禁止在日志中打印完整敏感信息'':22 ''禁止拼接'':4 ''系统中模型生成的参数'':11 ''身份证等'':19', '[-0.03450021,-0.010274601,-0.07879129,0.05444958,-0.0658271,-0.07109018,0.034384117,0.03682216,0.010613218,0.015353853,-0.02594772,-0.0030354576,0.033474687,0.027785927,0.04500701,-0.036009476,0.013728492,0.01049712,-0.004863988,-0.018662622,-0.03434542,0.051740646,-0.03949239,0.004404437,-0.007478594,0.037344594,-0.05646193,-0.045200504,0.056616727,-0.0036570614,0.032062173,-0.047328953,-0.0036522239,-0.019833269,-0.027089342,-0.023142038,0.0025251138,-0.013312478,-0.1029395,0.04698066,-0.015208731,-0.015527998,-0.0021151456,-0.0018236933,0.057506807,-0.013863939,0.016988888,-0.059557855,0.023722524,-0.041756287,-0.026895847,-0.017521,0.034384117,-0.0701614,0.031617135,0.0076479022,0.006157988,-0.008716963,-0.009607042,0.024651302,-0.05193414,-0.03295225,-0.017085636,0.022522854,0.025831623,0.0060031917,0.01378654,0.008015543,-0.0029822465,-0.050618373,-0.0075366423,0.044310424,0.026566906,-0.00835416,-0.068342544,0.0055823396,0.022174561,0.022909844,-0.07797861,0.026025118,0.057893798,-0.02025896,0.021303833,-0.012054757,0.007972007,0.057893798,0.026992595,0.022929193,0.014115483,0.015944013,0.016988888,-0.058861274,0.05112146,-0.0370737,-0.014995886,0.006941644,0.04895431,0.024496505,0.01979457,0.06563361,0.01195801,-0.028579257,-0.026547557,-0.03250721,0.0739926,0.015576372,0.0453553,0.024496505,-0.035370942,-0.022793747,-0.0013145588,0.040943608,0.053404704,0.0371124,-0.008678265,-0.06520792,0.028347062,0.0059451433,-0.009447409,0.027805276,0.045858387,0.016601898,0.0057177865,-0.043962132,0.02637341,-0.007947819,-0.030843152,0.051276255,0.016534174,0.02968218,-0.008344485,-0.004762403,-0.055842746,-0.01670832,-0.11849653,-0.009636066,-0.044813514,