-- Table structure for kb_document
-- ----------------------------
DROP TABLE IF EXISTS "public"."kb_document";
CREATE TABLE "public"."kb_document" (
  "id" int8 NOT NULL DEFAULT nextval('kb_document_id_seq'::regclass),
  "kb_id" int8 NOT NULL,
  "file_name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "file_type" varchar(20) COLLATE "pg_catalog"."default" NOT NULL,
  "file_size" int8 NOT NULL,
  "minio_path" varchar(500) COLLATE "pg_catalog"."default" NOT NULL,
  "status" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'PENDING'::character varying,
  "error_msg" text COLLATE "pg_catalog"."default",
  "chunk_count" int4 DEFAULT 0,
  "token_count" int4 DEFAULT 0,
  "version" int4 NOT NULL DEFAULT 1,
  "uploaded_by" int8 NOT NULL,
  "uploaded_at" timestamp(6) NOT NULL DEFAULT now(),
  "indexed_at" timestamp(6),
  "is_deleted" bool NOT NULL DEFAULT false
)
;
COMMENT ON COLUMN "public"."kb_document"."version" IS '每次重建索引版本号加1，旧版本分块通过版本号识别并删除';
COMMENT ON TABLE "public"."kb_document" IS '上传到知识库的文档，一个文档对应多个分块';

