-- ----------------------------
-- Table structure for kb_index_task
-- ----------------------------
DROP TABLE IF EXISTS "public"."kb_index_task";
CREATE TABLE "public"."kb_index_task" (
  "id" int8 NOT NULL DEFAULT nextval('kb_index_task_id_seq'::regclass),
  "doc_id" int8 NOT NULL,
  "task_type" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'INDEX'::character varying,
  "status" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'PENDING'::character varying,
  "retry_count" int4 NOT NULL DEFAULT 0,
  "max_retry" int4 NOT NULL DEFAULT 3,
  "error_msg" text COLLATE "pg_catalog"."default",
  "created_at" timestamp(6) NOT NULL DEFAULT now(),
  "started_at" timestamp(6),
  "finished_at" timestamp(6),
  "payload" jsonb
)
;
COMMENT ON COLUMN "public"."kb_index_task"."payload" IS '索引任务扩展载荷，例如文档替换时暂存待发布文件元数据';

