-- ----------------------------
-- Checks structure for table kb_eval_result
-- ----------------------------
ALTER TABLE "public"."kb_eval_result" ADD CONSTRAINT "ck_eval_result_status" CHECK (status::text = ANY (ARRAY['SUCCESS'::character varying, 'PARTIAL'::character varying, 'FAILED'::character varying]::text[]));
ALTER TABLE "public"."kb_eval_result" ADD CONSTRAINT "ck_eval_result_rank" CHECK (rank IS NULL OR rank >= 1 AND rank <= 5);
ALTER TABLE "public"."kb_eval_result" ADD CONSTRAINT "ck_eval_result_scores" CHECK ((faithfulness IS NULL OR faithfulness >= 0.0::double precision AND faithfulness <= 1.0::double precision) AND (answer_relevancy IS NULL OR answer_relevancy >= 0.0::double precision AND answer_relevancy <= 1.0::double precision) AND (context_recall IS NULL OR context_recall >= 0.0::double precision AND context_recall <= 1.0::double precision) AND (context_precision IS NULL OR context_precision >= 0.0::double precision AND context_precision <= 1.0::double precision));

